fn frame(t: i32) {
    let w: i32 = host::display::width();
    let bx: i32 = w / 2 - 70;
    let by: i32 = 120;
    let down: i32 = host::display::pointer_down();
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let inside: i32 = if px >= bx && px < bx + 140 && py >= by && py < by + 56 { 1 } else { 0 };
    let mut holdf: i32 = host::display::state_get(0);
    let mut locked: i32 = host::display::state_get(1);
    if down == 1 && inside == 1 {
        holdf = holdf + 1;
        if holdf == 45 {
            locked = 1 - locked;
            host::display::state_set(1, locked);
        }
    } else {
        holdf = 0;
    }
    host::display::state_set(0, holdf);
    host::display::clear(0x101010);
    let bc: i32 = if locked == 1 { 0x883030 } else { 0x306688 };
    host::display::fill_rect(bx, by, 140, 56, bc);
    if locked == 1 {
        host::display::draw_string(bx + 34, by + 24, "LOCKED", 0xffffff, 1);
    } else {
        host::display::draw_string(bx + 22, by + 24, "UNLOCKED", 0xffffff, 1);
    }
    if down == 1 && inside == 1 && holdf < 45 {
        host::display::fill_rect(bx, by + 64, 140, 6, 0x282828);
        host::display::fill_rect(bx, by + 64, holdf * 140 / 45, 6, 0xffcc00);
    }
    host::display::draw_string(bx - 20, by - 30, "HOLD 45 FRAMES TO TOGGLE", 0x808080, 1);
    host::display::present();
}
